package com.backendSupermercado.supermercasdo.modules.reportes.cliente.model;
public enum TipoReporteCliente { CLIENTES("clientes-general","Reporte general de clientes"), COMPRAS("compras-cliente","Reporte de compras por cliente"), FRECUENTES("clientes-frecuentes","Reporte de clientes frecuentes"), CREDITOS("creditos-general","Reporte general de créditos"), PENDIENTES("creditos-pendientes","Reporte de créditos pendientes"), VENCIDOS("creditos-vencidos","Reporte de créditos vencidos"), PAGOS("pagos-creditos","Reporte de pagos de créditos"), SALDOS("saldos-cliente","Reporte de saldos por cliente"), RECUPERACION("recuperacion-creditos","Reporte de recuperación de créditos"); private final String ruta,titulo; TipoReporteCliente(String r,String t){ruta=r;titulo=t;} public String ruta(){return ruta;}public String titulo(){return titulo;}public static TipoReporteCliente desdeRuta(String r){for(var t:values())if(t.ruta.equalsIgnoreCase(r))return t;throw new IllegalArgumentException("Reporte de clientes no válido");}}
